import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec4, uv, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Vector3 } = ctx.THREE;

  // Root Container
  const group = new Group();

  // Active GSAP timelines tracker for cleanup
  const activeTimelines = [];

  // Define colors from spec
  const colorInk = '#16161d';
  const colorPaper = '#e8ecf2';
  const colorAccent = '#ff2a38';
  const colorSurface = '#0b0b10';

  // 1. STAGE: Create backdrop to avoid FLAT_VOID (7x6 at z = -2.5)
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // Custom vertical gradient via TSL
  const uvs = uv();
  const topColor = vec4(0.086, 0.086, 0.114, 1.0); // #16161d
  const bottomColor = vec4(0.043, 0.043, 0.063, 1.0); // #0b0b10
  backdropMat.colorNode = mix(bottomColor, topColor, uvs.y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // 2. LIGHTING (Product-shot local setup)
  const keyLight = new DirectionalLight(colorPaper, 1.0);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colorAccent, 0.8);
  rimLight.position.set(-2, -1, -1);
  group.add(rimLight);

  // Create local containers for animated content to separate hover offsets
  const contentGroup = new Group();
  group.add(contentGroup);

  // 3. GLB LOAD AND STYLING (The Machined Rule Element)
  const meshUrl = config.meshUrl || '/prism-mock/home/nodes/cta-hero.glb';

  ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
    const model = gltf.scene;

    // Scale and position model appropriately for a divider
    model.scale.set(1.2, 0.2, 0.2); // Squeezes to act as a decorative divider rule
    model.position.set(0, 0, 0);

    model.traverse((child) => {
      if (child.isMesh) {
        // Machined Metal look for general surfaces
        const mat = new MeshStandardNodeMaterial({
          color: colorPaper,
          metalness: 0.55,
          roughness: 0.2,
          clearcoat: 0.25,
          transparent: true,
          opacity: 0.95
        });

        // Jewel highlights: Detect any central / smaller parts of the mesh or default to red emissive accent
        if (child.name.toLowerCase().includes('jewel') || child.name.toLowerCase().includes('accent') || child.scale.x < 0.2) {
          mat.color.set(colorAccent);
          mat.emissive.set(colorAccent);
          mat.emissiveIntensity = 2.0;
          mat.roughness = 0.15;
          mat.metalness = 0.1;
        }

        child.material = mat;
      }
    });

    contentGroup.add(model);

    // Jewel breathing/glowing idle effect
    const emissiveTl = gsap.timeline({ repeat: -1, yoyo: true });
    model.traverse((child) => {
      if (child.isMesh && child.material.emissiveIntensity !== undefined) {
        emissiveTl.to(child.material, {
          emissiveIntensity: 0.8,
          duration: 2.0,
          ease: 'power1.inOut'
        }, 0);
      }
    });
    activeTimelines.push(emissiveTl);
  }).catch((err) => {
    console.warn("Failed to load ornamental divider GLB, placing fallback geometry:", err);
    // Fallback: A thin rule with a central diamond jewel
    const ruleGeo = new PlaneGeometry(4, 0.02);
    const ruleMat = new MeshStandardNodeMaterial({ color: colorPaper, metalness: 0.5, roughness: 0.3 });
    const rule = new Mesh(ruleGeo, ruleMat);
    contentGroup.add(rule);

    const jewelGeo = new PlaneGeometry(0.12, 0.12);
    const jewelMat = new MeshStandardNodeMaterial({
      color: colorAccent,
      emissive: colorAccent,
      emissiveIntensity: 1.8,
      roughness: 0.1
    });
    const jewel = new Mesh(jewelGeo, jewelMat);
    jewel.rotation.z = Math.PI / 4;
    jewel.position.z = 0.01;
    contentGroup.add(jewel);

    // Breathe fallback jewel
    const fallbackTl = gsap.to(jewelMat, {
      emissiveIntensity: 0.6,
      duration: 1.5,
      yoyo: true,
      repeat: -1,
      ease: 'power2.inOut'
    });
    activeTimelines.push(fallbackTl);
  });

  // Contact shadow under the divider
  const shadowGeo = new PlaneGeometry(4.2, 0.05);
  const shadowMat = new MeshBasicNodeMaterial({
    color: colorSurface,
    transparent: true,
    opacity: 0.6
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.1, -0.05);
  contentGroup.add(shadow);

  // 4. INTERACTION BEHAVIORS & EVENT HANDLERS
  let isHovered = false;

  group.userData.handlers = {
    pointerover: () => {
      if (isHovered) return;
      isHovered = true;

      // Subtle rise-in animation (+0.15 scene units on hover)
      const hoverTl = gsap.timeline();
      hoverTl.to(contentGroup.position, {
        y: 0.15,
        z: 0.1,
        duration: 0.5,
        ease: 'power3.out'
      });
      activeTimelines.push(hoverTl);
    },
    pointerout: () => {
      isHovered = false;
      const hoverTl = gsap.timeline();
      hoverTl.to(contentGroup.position, {
        y: 0,
        z: 0,
        duration: 0.4,
        ease: 'power3.out'
      });
      activeTimelines.push(hoverTl);
    },
    pointerdown: () => {
      // Press-down effect
      const pressTl = gsap.timeline();
      pressTl.to(contentGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
      activeTimelines.push(pressTl);

      // Emit selection event
      ctx.emit('hub-home.select', { id: config.id, target: 'confirmPanel' });
    },
    pointerup: () => {
      const releaseTl = gsap.timeline();
      releaseTl.to(contentGroup.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.3,
        ease: 'power4.out'
      });
      activeTimelines.push(releaseTl);
    }
  };

  // 5. CLEANUP DESTRUCTOR
  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    keyLight.dispose();
    rimLight.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    // Dispose loaded model elements
    contentGroup.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  return group;
}
